import os, figs
from figs import page, OUT
F={}
A="<div class='arrow' style='font-size:26px'>→</div>"
D="<div class='arrow' style='font-size:24px;margin:4px 0'>↓</div>"
def q(t,sub=""): return f"<div class='card' style='background:#002333;border-color:#002333;color:#fff;padding:16px 22px'><div class='t' style='font-size:21px;font-weight:700'>{t}</div>{sub}</div>"
def leaf(t,s,sty): return f"<div class='card' style='padding:14px 18px;{sty}'><div class='t' style='font-size:20px;font-weight:700'>{t}</div><div style='font-size:16px;margin-top:2px;opacity:.85'>{s}</div></div>"
# f1 decision tree
F['57-f1-rubric-type']=("Decision tree: which Blackboard Ultra rubric type",
 "<h1>Which rubric type?</h1><div class='sub'>Two questions pick the type: do you need a number, and do you need room inside a level.</div>"
 +q("1 · Does this work need a numerical grade?")
 +"<div class='row' style='margin:10px 0 0 48px;align-items:center;gap:14px'><div class='lab' style='width:50px;color:#5b7480'>No</div><div style='flex:1'>"+leaf("No-points rubric","Feedback levels only, no score","background:#e7eef0;border:none")+"</div></div>"
 +"<div class='row' style='margin:16px 0 0 48px;align-items:center;gap:14px'><div class='lab' style='width:50px;color:#5b7480'>Yes</div><div style='flex:1'>"+q("2 · Will the assignment’s point value change, or do you want weights to show?").replace("background:#002333;border-color:#002333","background:#2c4a57;border-color:#2c4a57")+"</div></div>"
 +"<div class='row' style='margin:12px 0 0 120px;gap:20px'><div style='flex:1'><div class='lab' style='color:#5b7480;margin-bottom:8px'>Yes: percentages</div>"+q("3 · Room inside a level?").replace("background:#002333;border-color:#002333","background:#5b7480;border-color:#5b7480")+"<div class='row' style='gap:10px;margin-top:10px'><div style='flex:1'>"+leaf("Percentage-based","No","background:#002333;color:#fff;border:none")+"</div><div style='flex:1'>"+leaf("Percentage-range","Yes","background:#fff;border:3px solid #002333")+"</div></div></div>"
 +"<div style='flex:1'><div class='lab' style='color:#5b7480;margin-bottom:8px'>No: points</div>"+q("4 · Room inside a level?").replace("background:#002333;border-color:#002333","background:#5b7480;border-color:#5b7480")+"<div class='row' style='gap:10px;margin-top:10px'><div style='flex:1'>"+leaf("Points-based","No","background:#cfeadf;border:none")+"</div><div style='flex:1'>"+leaf("Points-range","Yes","background:#fff;border:3px solid #007b54")+"</div></div></div></div>"
 +"<div class='foot'>Decide before writing descriptors: switching type later can clear them.</div>")
def pathbox(t,hi=False): return f"<div class='card' style='padding:14px 18px;{'background:#002333;border-color:#002333;color:#fff' if hi else ''}'><div class='t' style='font-size:20px;font-weight:700'>{t}</div></div>"
def pathrow(items,hi_last=False): return "<div class='row' style='gap:8px;align-items:stretch'>"+A.join(f"<div style='flex:1'>{pathbox(t,hi_last and i==len(items)-1)}</div>" for i,t in enumerate(items))+"</div>"
F['57-f2-two-routes']=("Two routes to the Course Rubrics page in Blackboard Ultra, schematic",
 "<h1>Two routes to the Course Rubrics page</h1><div class='sub'>Schematic click path, not a screenshot.</div>"
 "<div class='lab'>Route A · from the Gradebook</div><div style='margin:10px 0 26px'>"+pathrow(["Gradebook","Gradebook Settings (gear)","Course Rubrics section","Manage Course Rubrics"])+"</div>"
 "<div class='lab'>Route B · from the assignment</div><div style='margin:10px 0 26px'>"+pathrow(["Assignment","Settings","Grading &amp; Submissions","Add Rubric"])+"</div>"
 "<div class='arrow' style='font-size:26px'>↓ both routes end here ↓</div>"+"<div style='margin-top:8px'>"+pathrow(["Course Rubrics page","Create","Name and type","Edit cells, Save"],True)+"</div>"
 "<div class='foot'>From Route B you can also select a rubric and attach it with Save &amp; Close.</div>")
F['57-f3-rubric-anatomy']=("Anatomy of an Ultra rubric and its limits, schematic",
 "<h1>Anatomy of an Ultra rubric</h1><div class='sub'>Schematic, not a screenshot. The limits shape how you write each cell.</div>"
 "<div class='card' style='padding:0;overflow:hidden'><div style='background:#002333;color:#fff;padding:14px 22px;font-size:19px'><b>Rubric title</b> · 255 characters max</div>"
 "<div class='row' style='gap:0'><div style='width:200px;padding:14px;background:#f3f7f8'></div>"+"".join(f"<div style='flex:1;padding:14px;background:#e7eef0;border-left:2px solid #fff'><div class='t' style='font-size:19px;font-weight:700'>{a}</div><div style='font-size:14px;color:#5b7480'>title: 40 characters max</div></div>" for a in ["Level 1 (highest)","Level 2","Level 3","Level 4 (lowest)"])+"</div>"
 +"".join(f"<div class='row' style='gap:0;border-top:2px solid #e7eef0'><div style='width:200px;padding:14px;background:#f3f7f8'><div class='t' style='font-size:19px;font-weight:700'>Criterion {i}</div><div style='font-size:14px;color:#5b7480'>1,000 characters max</div></div>"+"".join("<div style='flex:1;padding:14px;border-left:2px solid #e7eef0'><div style='height:10px;border-radius:5px;background:#e7eef0;margin-bottom:8px'></div><div style='height:10px;width:70%;border-radius:5px;background:#e7eef0'></div></div>" for _ in range(4))+"</div>" for i in range(1,5))+"</div>"
 "<div class='row' style='margin-top:20px;gap:14px;flex-wrap:wrap'>"+"".join(f"<div class='card' style='flex:1;min-width:240px;padding:14px 16px'><div class='lab' style='font-size:14px'>{n}</div><div class='s' style='font-size:17px;margin-top:4px;color:#002333'>{t}</div></div>" for n,t in [("① Default size","4 rows by 4 columns; add or delete as needed"),("② Plain text only","Pasted formatting is dropped"),("③ Enter","Confirms and exits edit mode; no new line"),("④ Column order","Always highest to lowest")])+"</div>")
steps4=[("Describe","Assignment, outcome, audience",0),("Choose","Type, complexity, rows and columns",0),("Generate","The AI drafts the rubric",1),("Review every cell","Observable? Distinguishable? Matches your outcomes?",2),("Edit","Level titles to 40 characters; tie to your assignment",2),("Continue to save","",0),("Test","Two sample submissions",2)]
def sc(i,a,b,k):
    sty={0:"",1:"background:#e7eef0",2:"background:#002333;border-color:#002333;color:#fff"}[k]
    return f"<div class='card' style='flex:1;padding:14px;{sty}'><div class='num' style='width:34px;height:34px;font-size:17px;{'background:#fff;color:#002333' if k==2 else ''}'>{i}</div><div class='t' style='font-size:18px;font-weight:700;margin-top:10px'>{a}</div><div style='font-size:15px;line-height:1.35;margin-top:5px;{'color:rgba(255,255,255,.78)' if k==2 else 'color:#2c4a57'}'>{b}</div></div>"
F['57-f4-generate-flow']=("Generating a rubric with the AI Design Assistant: steps and who does what",
 "<h1>Generating a rubric is the start, not the end</h1><div class='sub'>Steps 4, 5 and 7 are yours. Dark cards are where the quality comes from.</div>"
 "<div class='row' style='gap:6px;align-items:stretch'>"+"<div class='arrow' style='font-size:20px'>→</div>".join(sc(i+1,a,b,k) for i,(a,b,k) in enumerate(steps4))+"</div>")
def tbar(lbl,segs,note=""):
    s="".join(f"<div style='width:{m/50*700}px;height:44px;background:{c};{'border-radius:6px 0 0 6px' if i==0 else ''}{'border-radius:0 6px 6px 0' if i==len(segs)-1 and len(segs)>1 else ''}{'border-radius:6px' if len(segs)==1 else ''};color:#fff;font-size:17px;display:flex;align-items:center;padding-left:12px'>{t}</div>" for i,(m,c,t) in enumerate(segs))
    tot=sum(m for m,_,_ in segs)
    return f"<div class='row' style='align-items:center;gap:16px;margin-top:18px'><div class='s' style='width:220px;color:#002333;font-weight:600'>{lbl}</div><div class='row' style='gap:0'>{s}</div><div class='t' style='font-weight:700'>{tot} min</div></div><div class='s' style='margin-left:236px;font-size:16px;margin-top:4px'>{note}</div>"
F['57-f5-time-to-rubric']=("Time to a usable rubric, example minutes",
 "<div class='row' style='justify-content:space-between;align-items:center'><h1>Time to a usable rubric</h1><span class='ex'>EXAMPLE MINUTES</span></div><div class='sub'>Yours will differ. Review time is not optional.</div>"
 +tbar("Write from scratch",[(45,"#002333","write 16 cells")])
 +tbar("Generate, then review and edit",[(3,"#5b7480","3"),(22,"#002333","review, rewrite, test")],"The 22 minutes is where the rubric becomes yours.")
 +tbar("Copy an existing rubric and adjust",[(8,"#2c4a57","8")]))
def panel(h,col,crit,lvl,txt,notes):
    return f"<div class='card' style='flex:1;padding:0;overflow:hidden'><div style='background:{col};color:#fff;padding:12px 20px;font-weight:700;font-size:19px'>{h}</div><div style='padding:20px'><div class='lab' style='font-size:14px'>Criterion</div><div class='t' style='font-weight:700'>{crit}</div><div class='lab' style='font-size:14px;margin-top:14px'>Level</div><div class='t' style='font-size:21px'><b>{lvl}</b> {txt}</div><div style='margin-top:16px'>"+"".join(f"<div class='chip' style='background:#f3f7f8;color:#002333;font-size:16px;margin:4px 6px 4px 0;padding:6px 12px'>{n}</div>" for n in notes)+"</div></div></div>"
F['57-f6-descriptors']=("Same criterion, two descriptors: hard to apply versus easier to apply",
 "<div class='row' style='justify-content:space-between;align-items:center'><h1>Same criterion, two descriptors</h1><span class='ex'>EXAMPLE</span></div><div class='sub'>Descriptors for a policy memo.</div>"
 "<div class='row' style='gap:24px;align-items:stretch'>"+panel("Hard to apply","#b3261e","Use of evidence","Proficient:","Uses good evidence to support the argument.",["What is “good”?","How much is enough?","Two graders, two answers"])
 +panel("Easier to apply","#007b54","Use of evidence","Proficient (75%):","Uses two or three sources from the course packet; each main claim has a source, but one claim has none.",["Countable: 2 to 3 sources","Checkable: a claim without a source","Next level up: all claims sourced"])+"</div>")
F['57-f7-grade-with-rubric']=("Click path for grading with a rubric in Blackboard Ultra, schematic",
 "<h1>Grading with a rubric</h1><div class='sub'>Schematic click path. Scores and criterion feedback save automatically; nothing reaches the student until you post.</div>"
 "<div class='row' style='gap:8px;align-items:stretch'>"+A.join(f"<div style='flex:1'>{pathbox(t)}</div>" for t in ["Gradebook","Select the assessment","Submissions","Select a student name"])+"</div>"
 "<div class='arrow' style='justify-content:flex-end;padding-right:100px;margin:8px 0'>↓</div>"
 "<div class='row' style='gap:8px;align-items:stretch'>"+A.join(f"<div style='flex:1'>{pathbox(t)}</div>" for t in ["Rubric icon beside the grade pill (side panel) or expand icon (movable window)","Select a score pill per criterion","Optional criterion feedback","Close the panel (X)"])+"</div>"
 "<div class='arrow' style='justify-content:flex-end;padding-right:100px;margin:8px 0'>↓</div>"
 "<div class='row' style='gap:8px;align-items:stretch'>"+A.join(f"<div style='flex:1'>{pathbox(t,i==2)}</div>" for i,t in enumerate(["Feedback icon for overall feedback","Menu","Post"]))+"</div>")
def st(n,t,sub,sty,lock=""): return f"<div class='card' style='flex:1;padding:16px;{sty}'><div class='lab' style='font-size:14px;opacity:.8'>State {n}</div><div class='t' style='font-size:20px;font-weight:700;margin-top:6px'>{lock}{t}</div><div style='font-size:16px;margin-top:6px;opacity:.85'>{sub}</div></div>"
F['57-f8-rubric-lifecycle']=("What happens when you change a rubric that has been used, schematic",
 "<h1>A used rubric is locked</h1><div class='sub'>Schematic lifecycle. Copying creates an editable version.</div>"
 "<div class='row' style='gap:6px;align-items:stretch'>"+st(1,"Draft rubric","Editable","")+"<div class='arrow' style='flex-direction:column;font-size:14px;width:90px;text-align:center'>attach to assignment<span style='font-size:22px'>→</span></div>"+st(2,"In use, nothing graded yet","Editable","")+"<div class='arrow' style='flex-direction:column;font-size:14px;width:70px;text-align:center'>grade<span style='font-size:22px'>→</span></div>"+st(3,"Used for grading","Locked","background:#002333;border-color:#002333;color:#fff","")+"<div class='arrow' style='flex-direction:column;font-size:14px;width:110px;text-align:center'>Create a Copy or Duplicate<span style='font-size:22px'>→</span></div>"+st(4,"New rubric","Associated with the item","background:#e6f4ee;border:none")+"</div>"
 "<div class='row' style='margin-top:22px;gap:20px'><div class='card' style='flex:1'><div class='lab' style='font-size:14px'>Below state 4</div><div class='t' style='font-size:20px;margin-top:6px'>Earlier grades are preserved but converted to <b>overrides</b>. Regrade with the new rubric to restore rubric scoring.</div></div>"
 "<div class='card' style='flex:1'><div class='lab' style='font-size:14px'>Side branch from state 3</div><div class='t' style='font-size:20px;margin-top:6px'>Delete the rubric: grades remain as <b>manually added</b> grades.</div></div></div>")
def pb(l,pos,avg,ratio=1.0):
    return f"<div class='row' style='align-items:center;gap:14px;margin-top:12px'><div class='s' style='width:110px;color:#002333;font-weight:600'>{l}</div><div style='width:{pos/40*330}px;height:36px;background:#cdd9de;border-radius:6px;position:relative'><div style='width:{avg/40*330}px;height:36px;background:#002333;border-radius:6px'></div></div><div class='s' style='font-size:17px;white-space:nowrap'>{avg} of {pos}</div></div>"
F['57-f9-evaluation-report']=("Rubric Evaluation Report: what to look for, example data, schematic",
 "<div class='row' style='justify-content:space-between;align-items:center'><h1>Reading the Rubric Evaluation Report</h1><span class='ex'>EXAMPLE DATA</span></div><div class='sub'>Schematic. The report sections: Overview, Rubric Overall Performance, Rubric Analysis, Frequency Distribution.</div>"
 "<div class='row' style='gap:24px;align-items:flex-start'><div class='card' style='flex:1.2'><div class='lab'>Average earned per criterion</div>"+pb("Argument",40,29)+pb("Evidence",30,17)+pb("Structure",20,18)+pb("Citations",10,9)+"<div class='s' style='font-size:16px;margin-top:12px'>Light bar: points possible. Dark bar: average earned.</div></div>"
 "<div class='card' style='flex:1'><div class='lab'>Frequency distribution: Structure</div><div class='row' style='margin-top:12px;font-weight:700;font-size:17px;border-bottom:2px solid #e7eef0;padding-bottom:6px'><div style='flex:1'>Level</div><div style='flex:1'>Share of students</div></div>"+"".join(f"<div class='row' style='padding:8px 0;font-size:20px;{'background:#fbf1e3;' if lv=='100%' else ''}'><div style='flex:1'>{lv}</div><div style='flex:1'>{sh}</div></div>" for lv,sh in [("100%","78%"),("75%","17%"),("50%","5%")])+"</div></div>"
 "<div class='row' style='margin-top:20px;gap:20px'><div class='card warn' style='flex:1;border:none'><div class='t' style='font-size:19px;color:#002333'><b>Structure: ceiling effect.</b> 78% at the top level. Is the descriptor too easy, or is the class strong?</div></div><div class='card warn' style='flex:1;border:none'><div class='t' style='font-size:19px;color:#002333'><b>Evidence: lowest average (57%).</b> Check the descriptor before you re-teach.</div></div></div>")
def fs(i,a,b,k): 
    sty="background:#002333;border-color:#002333;color:#fff" if k else ""
    return f"<div class='card' style='flex:1;padding:16px;{sty}'><div class='num' style='width:34px;height:34px;font-size:17px;{'background:#fff;color:#002333' if k else ''}'>{i}</div><div class='t' style='font-size:19px;font-weight:700;margin-top:10px'>{a}</div><div style='font-size:16px;line-height:1.4;margin-top:6px;{'color:rgba(255,255,255,.78)' if k else 'color:#2c4a57'}'>{b}</div></div>"
F['57-f10-eduface-flow']=("From a Blackboard Ultra submission to an approved grade with Eduface",
 "<h1>The grade returns only after you approve it</h1><div class='sub'>Eduface works from your rubric. The instructor decides.</div>"
 "<div class='row' style='gap:8px;align-items:stretch'>"+A.join(fs(i+1,a,b,i==2) for i,(a,b) in enumerate([("Student submits","In Blackboard Ultra"),("Open Eduface","From Blackboard, via LTI 1.3"),("Eduface suggests","A score per criterion against your rubric, held as a draft"),("Instructor reviews","Edits and approves"),("Approved grade returns","To the Blackboard gradebook")]))+"</div>")
for k,(alt,body) in F.items():
    open(os.path.join(OUT,k+'.html'),'w').write(page(body)); open(os.path.join(OUT,k+'.alt'),'w').write(alt)
print(len(F))
